import pandas as pd
import re
from datetime import datetime

df = pd.read_csv(r"D:\Anuj\Pearl-ASsignment\amazon-products.csv", dtype=str, keep_default_na=False)

dates = df[df['date_first_available'] != '']['date_first_available']

def parse_date(d_str):
    cleaned = re.sub(r'[\u200e\u200f]', '', d_str).strip()
    if not cleaned:
        return ''
    # formats: 'February 17, 2022', '25 November 2023', etc.
    for fmt in ('%B %d, %Y', '%d %B %Y', '%b %d, %Y', '%d %b %Y', '%Y-%m-%d'):
        try:
            return datetime.strptime(cleaned, fmt).strftime('%Y-%m-%d')
        except ValueError:
            pass
    # Try dateutil if needed
    try:
        from dateutil import parser
        return parser.parse(cleaned).strftime('%Y-%m-%d')
    except:
        return cleaned

parsed = dates.apply(parse_date)
failed = parsed[parsed.str.len() != 10]
print(f"Total dates: {len(dates)}")
print(f"Successfully converted to YYYY-MM-DD: {(parsed.str.len() == 10).sum()}")
print(f"Failed conversions: {len(failed)}")
if len(failed) > 0:
    print("Samples of failed:", failed.head(5))

